import {TODAY, money, proposalFor, availableDue, availablePayment, allocatedCents, pendingCents, reminderBlocker} from './domain.js';
import {METHODS} from './import.js';

export const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));
const paths = {
  dashboard: '<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
  upload: '<path d="M12 16V3m-5 5 5-5 5 5M4 15v5a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-5"/>',
  check: '<path d="m5 12 4 4L20 5"/>', clock: '<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  wallet: '<path d="M4 5h14v4M4 5a2 2 0 0 0 0 4h17v12H4a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2zM21 12h-5v5h5"/>',
  users: '<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 5a3 3 0 0 1 0 6M21 21v-3a6 6 0 0 0-3-5"/>',
  box: '<path d="m12 2 9 5-9 5-9-5 9-5zM3 7v10l9 5 9-5V7M12 12v10M7.5 4.5l9 5"/>',
  bell: '<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',
  link: '<path d="m10 13 4-4M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2 1 2-2a4 4 0 1 1 6 6l-5 5a4 4 0 0 1-6 0"/>',
  refresh: '<path d="M20 7V3l-3 3a8 8 0 1 0 3 9M20 3h-4"/>', arrow: '<path d="M4 12h16m-5-5 5 5-5 5"/>',
  download: '<path d="M12 3v13m-5-5 5 5 5-5M4 16v5h16v-5"/>', info: '<circle cx="12" cy="12" r="9"/><path d="M12 10v7m0-11v.5"/>',
  close: '<path d="m6 6 12 12M6 18 18 6"/>', menu: '<path d="M4 6h16M4 12h16M4 18h16"/>', file: '<path d="M14 2H4v20h16V8l-6-6zM14 2v6h6M8 13h8M8 17h6"/>',
  shield: '<path d="m12 2 8 3v6c0 5-4 9-8 11-4-2-8-6-8-11V5l8-3zM8 12l3 3 5-6"/>',
};
export const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name] || paths.file}</svg>`;
export const btn = (text, action, id = '', cls = '', ico = '', disabled = false) => `<button type="button" class="btn ${cls}" data-action="${action}" data-id="${esc(id)}"${disabled ? ' disabled' : ''}>${ico ? icon(ico) : ''}${esc(text)}</button>`;
const link = (text, page, cls = 'btn', ico = '') => `<a href="#/${page}" class="${cls}">${ico ? icon(ico) : ''}${esc(text)}</a>`;
const date = s => s ? new Date(s.slice(0, 10) + 'T12:00:00Z').toLocaleDateString('fr-CH', {day: 'numeric', month: 'short'}) : '—';
const time = s => s ? new Date(s).toLocaleTimeString('fr-CH', {hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Zurich'}) : '—';
const avatar = (name, i = 0) => `<span class="avatar ${i % 2 ? 'blue' : ''}">${esc(name.split(' ').slice(0, 2).map(x => x[0]).join(''))}</span>`;
export const chip = (label, color = '') => `<span class="chip ${color}"><i></i>${esc(label)}</span>`;
export const STATUS = {matched: ['Référence reconnue', ''], partial: ['Paiement partiel', 'blue'], overpayment: ['Surplus à vérifier', 'amber'], review: ['À vérifier', 'amber'], queued: ['Prêt à simuler', 'purple'], uncertain: ['Confirmation à vérifier', 'red'], synced: ['Enregistré en simulation', ''], excluded: ['Traitement séparé', 'gray']};
const badge = p => chip(...(STATUS[p] || ['À vérifier', 'amber']));
const notice = (text, warn = false) => `<div class="notice ${warn ? 'warn' : ''}">${icon(warn ? 'info' : 'shield')}<span>${text}</span></div>`;
const empty = (title, text, action = '') => `<div class="empty">${icon('wallet')}<h3>${esc(title)}</h3><p>${esc(text)}</p>${action}</div>`;
const clientFor = (s, i) => s.clients.find(c => c.id === i.clientId) || {name: 'Client inconnu'};
const unitFor = (s, i) => s.units.find(u => u.id === i.unitId) || {label: '—'};
export const filterPayments = (s, u) => s.payments.filter(p => {
  const q = String(u.query || '').toLowerCase();
  if (q && ![p.customer, p.transactionId, p.reference, p.method, p.description].join(' ').toLowerCase().includes(q)) return false;
  if (u.centre !== 'all') {const i = s.invoices.find(i => i.reference === p.reference); if (!i || clientFor(s, i).centre !== u.centre) return false;}
  const status = proposalFor(s, p).status;
  return !u.filter || u.filter === 'all' || u.filter === status || u.filter === 'review' && ['review', 'overpayment', 'uncertain'].includes(status) || u.filter === 'matched' && ['matched', 'partial'].includes(status);
});
function paymentTable(s, u, limit = 100) {
  const rows = filterPayments(s, u);
  if (!rows.length) return empty('Tout est clair dans cette vue.', 'Modifiez les filtres ou importez de nouvelles opérations.', link('Importer un fichier', 'import', 'btn', 'upload'));
  return `<div class="table-scroll"><table><thead><tr><th>Client / opération</th><th>Moyen / date</th><th>Montant</th><th>Rapprochement</th><th></th></tr></thead><tbody>${rows.slice(0, limit).map((p, i) => {
    const match = proposalFor(s, p); const invoice = s.invoices.find(x => x.id === match.invoiceId);
    return `<tr><td><div class="row">${avatar(p.customer || 'À identifier', i)}<div><strong>${esc(p.customer || (p.kind === 'settlement' ? 'Versement du prestataire' : 'Client à identifier'))}</strong><span class="micro">${esc(p.transactionId)}${invoice ? ' · ' + esc(unitFor(s, invoice).label) : ''}</span></div></div></td><td><span class="method">${icon(p.method === 'Espèces' ? 'wallet' : 'file')}${esc(p.method)}</span><div class="micro">${date(p.date)}</div></td><td class="amount">${esc(money(p.amountCents, p.currency))}${allocatedCents(s, p.id) > 0 ? `<div class="micro">${esc(money(allocatedCents(s, p.id), p.currency))} affectés</div>` : ''}</td><td>${badge(match.status)}<div class="micro" style="max-width:210px;margin-top:6px">${esc(match.reason)}</div></td><td>${btn('Ouvrir', 'payment', p.id, 'tiny', 'arrow')}</td></tr>`;
  }).join('')}</tbody></table></div><div class="card-foot row between"><span>${Math.min(rows.length, limit)} opération(s) sur ${rows.length} · Données fictives</span><span>CHF et autres devises distingués</span></div>`;
}
const head = (eyebrow, title, sub, actions = '') => `<div class="page-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${title}</h1><p>${sub}</p></div><div class="row wrap">${actions}</div></div>`;
function filters(s, u) {
  return `<div class="filters">${[['all', 'Tous'], ['matched', 'Reconnus'], ['review', 'À vérifier'], ['queued', 'Préparés'], ['synced', 'Simulés'], ['excluded', 'À part']].map(([id, label]) => `<button class="filter ${u.filter === id ? 'active' : ''}" data-action="filter" data-id="${id}" aria-pressed="${u.filter === id}">${label}<span>${filterPayments(s, {...u, query: '', centre: 'all', filter: id}).length}</span></button>`).join('')}</div>`;
}
function overview(s, u) {
  const recognized = filterPayments(s, {...u, filter: 'matched'});
  const review = s.payments.filter(p => ['review', 'overpayment', 'uncertain'].includes(proposalFor(s, p).status));
  const queue = s.operations.filter(op => ['queued', 'uncertain'].includes(op.status));
  const total = s.payments.filter(p => p.currency === 'CHF' && p.kind === 'payment').reduce((sum, p) => sum + p.amountCents, 0);
  return head('VOTRE JOURNÉE, PLUS SIMPLE', 'Les bons paiements.<br>Les bons dossiers.', 'Un espace pour comprendre les encaissements, vérifier les correspondances et préparer leur enregistrement.', link('Importer un fichier', 'import', 'btn primary', 'upload')) +
    `<section class="stat-grid" aria-label="Indicateurs du scénario"><article class="stat featured"><div class="stat-label">Références reconnues${icon('check')}</div><div class="stat-value">${recognized.length}</div><div class="stat-foot">À préparer après vérification</div></article><article class="stat"><div class="stat-label">À examiner${icon('info')}</div><div class="stat-value">${review.length}</div><div class="stat-foot">Référence, devise ou affectation</div></article><article class="stat"><div class="stat-label">Préparations en cours${icon('link')}</div><div class="stat-value">${queue.length}</div><div class="stat-foot">Connecteur SiteLink fictif</div></article><article class="stat"><div class="stat-label">Encaissements clients CHF${icon('wallet')}</div><div class="stat-value">${esc(money(total))}</div><div class="stat-foot">Hors versements globaux et remboursements</div></article></section>` +
    `<div class="grid-main"><div class="stack"><article class="card"><div class="card-head"><div><h2>Chaque règlement à sa place.</h2><p>Plusieurs moyens de paiement, un suivi commun.</p></div>${btn('Préparer les reconnus', 'prepare-matches', '', 'soft tiny', 'check', recognized.length === 0)}</div>${filters(s, u)}${paymentTable(s, u)}</article>${queue.length ? `<div class="notice"><div class="grow"><strong>${queue.length} préparation(s) à vérifier</strong><p class="micro">L’étape suivante teste l’enregistrement dans un faux SiteLink.</p></div>${btn('Simuler l’enregistrement', 'sync', '', 'primary', 'link')}</div>` : ''}</div><aside class="stack"><article class="card"><div class="card-head"><h2>Essayez le parcours.</h2></div><div class="card-body"><ol class="step-list"><li><strong>Regardez un encaissement</strong><p>Ouvrez Emma Laurent : la référence retrouve son dossier.</p></li><li><strong>Préparez le rapprochement</strong><p>Confirmez la facture et le montant à affecter.</p></li><li><strong>Testez l’enregistrement</strong><p>Le connecteur fictif met à jour le solde et fournit un reçu simulé.</p></li></ol></div></article><article class="card"><div class="card-head"><h2>Tous vos moyens.</h2></div><div class="card-body">${METHODS.map(m => `<div class="mini-row"><span class="method">${icon('wallet')}${m}</span><span class="muted">${s.payments.filter(p => p.method === m).length} opération(s)</span></div>`).join('')}<p class="micro muted mt">Les formats réels des banques et prestataires seront adaptés après réception de leurs exemples.</p></div></article></aside></div>`;
}
function importPage(s, u) {
  const preview = u.preview;
  return head('UN IMPORT, UNE VÉRIFICATION', 'Commencer par les encaissements.', 'Import CSV de travail. Utilisez uniquement des fichiers fictifs ou anonymisés dans cet atelier.', `<a class="btn" href="./examples/encaissements-multicanal.csv" download>${icon('download')}Exemple CSV</a>`) +
    `<article class="card"><div class="upload-head"><h2>Déposez un fichier ou collez son contenu.</h2><p>Le format distingue paiements clients, versements globaux des prestataires et remboursements. Les XML camt et formats propriétaires attendent leurs adaptateurs.</p></div><div class="card-body"><form data-form="analyze"><div class="field"><label for="csv-file">Fichier CSV fictif ou anonymisé · 1 Mo maximum</label><input id="csv-file" type="file" accept=".csv,.txt,text/csv,text/plain"></div><div class="form-grid"><div class="field"><label for="account">Compte ou caisse de cet export</label><input id="account" name="account" data-input="account" maxlength="100" required value="${esc(u.account)}"><small>Conservez cet identifiant lors des prochains imports du même compte.</small></div><div class="field"><label for="source">Source des opérations</label><input id="source" name="source" data-input="source" maxlength="100" required value="${esc(u.source)}"><small>La même source doit garder le même identifiant.</small></div></div><div class="field"><label for="csv-text">Contenu du fichier</label><textarea id="csv-text" name="csv" data-input="importText" spellcheck="false" maxlength="1048576">${esc(u.importText)}</textarea></div><div class="row between wrap mt"><span class="micro muted">${esc(u.filename)} · Aucune donnée envoyée à une banque ou à SiteLink.</span><button class="btn primary" type="submit">${icon('check')}Analyser le fichier</button></div></form></div></article>` +
    (preview ? `<article class="card mt"><div class="card-head"><div><h2>Vérifier avant d’importer.</h2><p>L’analyse ne modifie pas les dossiers ni les soldes.</p></div>${btn(`Importer ${preview.filter(r => r.importStatus === 'new').length} ligne(s) valide(s)`, 'commit-import', '', 'primary', 'upload', !preview.some(r => r.importStatus === 'new'))}</div><div class="card-body"><div class="preview-summary"><span>${u.parsed.total} ligne(s) lues</span><span>${preview.filter(r => r.importStatus === 'new').length} nouvelle(s)</span><span>${preview.filter(r => r.importStatus === 'duplicate').length} doublon(s)</span><span>${preview.filter(r => r.importStatus === 'conflict').length} conflit(s)</span><span>${u.parsed.errors.length} erreur(s)</span></div>${u.parsed.errors.length ? `<div class="error-list"><strong>Lignes exclues de l’import</strong><br>${u.parsed.errors.map(e => `Ligne ${e.row} : ${esc(e.message)}`).join('<br>')}</div>` : ''}${preview.some(r => r.importStatus === 'conflict') ? notice('Un même identifiant présente des données différentes. Ces lignes sont exclues et doivent être vérifiées dans la source.', true) : ''}</div><div class="table-scroll"><table><thead><tr><th>Transaction</th><th>Moyen</th><th>Montant</th><th>Référence</th><th>Contrôle</th></tr></thead><tbody>${preview.slice(0, 100).map(r => `<tr><td>${esc(r.transactionId)}</td><td>${esc(r.method)}</td><td class="amount">${esc(money(r.amountCents, r.currency))}</td><td>${esc(r.reference || '—')}</td><td>${chip({new: 'Nouvelle', duplicate: 'Déjà importée', conflict: 'Conflit à vérifier'}[r.importStatus], {new: '', duplicate: 'gray', conflict: 'red'}[r.importStatus])}</td></tr>`).join('')}</tbody></table></div><div class="card-foot">Aperçu limité à 100 lignes ; l’import traite l’ensemble des lignes valides.</div></article>` : '') +
    `<article class="card mt"><div class="card-head"><h2>Les derniers imports</h2></div><div class="card-body">${s.batches.slice(0, 5).map(b => `<div class="mini-row"><div><strong>${esc(b.filename)}</strong><p class="micro muted">${date(b.at)} à ${time(b.at)} · ${esc(b.account)} / ${esc(b.source)}</p></div><span class="small">${b.added} ajout(s) · ${b.duplicates} doublon(s) · ${b.errors.length + b.conflicts} erreur(s)</span></div>`).join('')}</div></article>`;
}
function clientsPage(s, u) {
  const clients = s.clients.filter(c => (u.centre === 'all' || c.centre === u.centre) && (!u.query || (c.name + c.email).toLowerCase().includes(u.query.toLowerCase())));
  return head('LES INFORMATIONS AU MÊME ENDROIT', 'Un dossier pour chaque client.', 'Locations, factures, règlements affectés et soldes provenant du système fictif.') + `<article class="card"><div class="table-scroll"><table><thead><tr><th>Client</th><th>Centre / box</th><th>Solde dans la source simulée</th><th>En préparation</th><th></th></tr></thead><tbody>${clients.map((client, index) => {
    const invoices = s.invoices.filter(i => i.clientId === client.id);
    return `<tr><td><div class="row">${avatar(client.name, index)}<div><strong>${esc(client.name)}</strong><span class="micro">${esc(client.email)}</span></div></div></td><td>${esc(client.centre)}<div class="micro">${s.units.filter(x => x.clientId === client.id).map(x => esc(x.label)).join(', ')}</div></td><td class="amount">${esc(money(invoices.reduce((sum, i) => sum + i.balanceCents, 0)))}</td><td>${esc(money(invoices.reduce((sum, i) => sum + pendingCents(s, i.id), 0)))}</td><td>${btn('Voir le dossier', 'client', client.id, 'tiny', 'arrow')}</td></tr>`;
  }).join('')}</tbody></table></div>${!clients.length ? empty('Aucun dossier trouvé', 'Essayez un autre nom ou un autre centre.') : ''}</article>`;
}
function paymentsPage(s, u) {return head('UNE TRACE POUR CHAQUE RÈGLEMENT', 'Vos paiements, en détail.', 'Montant d’origine conservé, affectations distinctes et historique consultable.', btn('Exporter le suivi', 'export', '', '', 'download')) + `<article class="card">${filters(s, u)}${paymentTable(s, u)}</article>`;}
function reminderPage(s) {
  const invoices = s.invoices.filter(i => i.balanceCents > 0 && i.due < TODAY);
  return head('DES RAPPELS QUI TIENNENT COMPTE DES PAIEMENTS', 'Relancer avec les bonnes informations.', 'Préparation de brouillons uniquement. Aucun email ou SMS n’est envoyé depuis cet atelier.') +
    notice(s.checkedThrough === TODAY ? 'Les encaissements du scénario ont été vérifiés pour le 2 novembre 2026.' : 'Avant de préparer les rappels, vérifiez les encaissements de tous les moyens de paiement et actualisez les dossiers.', s.checkedThrough !== TODAY) +
    `<div class="row wrap mt">${btn('Actualiser les dossiers fictifs', 'refresh', '', '', 'refresh')}${btn('J’ai vérifié tous les encaissements du scénario', 'confirm-coverage', '', 'soft', 'check')}</div><article class="card mt"><div class="card-head"><h2>Échéances dépassées</h2><span class="micro muted">Scénario du 2 novembre 2026</span></div><div class="table-scroll"><table><thead><tr><th>Client / facture</th><th>Échéance</th><th>Solde</th><th>Vérification</th><th></th></tr></thead><tbody>${invoices.map(i => {
      const reason = reminderBlocker(s, i.id);
      return `<tr><td><strong>${esc(clientFor(s, i).name)}</strong><span class="micro">${esc(i.reference)}</span></td><td>${date(i.due)}</td><td class="amount">${esc(money(i.balanceCents, i.currency))}</td><td><span class="micro">${esc(reason || 'Brouillon possible après votre vérification.')}</span></td><td>${btn('Préparer', 'reminder', i.id, 'tiny', 'file', !!reason)}</td></tr>`;
    }).join('')}</tbody></table></div>${!invoices.length ? empty('Aucune échéance à relancer', 'Les dossiers du scénario sont à jour.') : ''}</article>` +
    (s.reminders.length ? `<article class="card mt"><div class="card-head"><h2>Vos brouillons</h2></div><div class="card-body">${s.reminders.slice(0, 10).map(d => `<div class="mini-row"><div><strong>${esc(s.invoices.find(i => i.id === d.invoiceId)?.reference)}</strong><p class="micro muted">Préparé à ${time(d.createdAt)} · non envoyé</p></div>${btn('Relire', 'draft', d.id, 'tiny', 'file')}</div>`).join('')}</div></article>` : '');
}
function connectionPage(s) {
  const count = s.operations.filter(op => ['queued', 'uncertain'].includes(op.status)).length;
  return head('PRÉPARER LE RACCORDEMENT', 'Le parcours se teste dès maintenant.', 'Le connecteur de cet atelier est fictif. Les accès autorisés, formats et frais réels restent à confirmer.') +
    `<div class="two-col"><article class="card"><div class="card-head"><h2>SiteLink</h2>${chip('Simulation locale', 'purple')}</div><div class="card-body"><p class="small">Le faux connecteur lit les factures, enregistre les règlements préparés et renvoie une référence de reçu. Il ne contacte aucun service Storable.</p><div class="mini-row"><span>Version des données affichées</span><strong>${s.sourceRevision}</strong></div><div class="mini-row"><span>Version du système fictif</span><strong>${s.mockServer.revision}</strong></div><div class="mini-row"><span>Dernière actualisation</span><strong>${time(s.lastSyncAt)}</strong></div><div class="row wrap mt">${btn('Actualiser le scénario', 'refresh', '', '', 'refresh')}${btn('Simuler l’enregistrement', 'sync', '', 'primary', 'link', count === 0)}</div></div></article><article class="card"><div class="card-head"><h2>Banque et prestataires</h2>${chip('Informations attendues', 'amber')}</div><div class="card-body"><p class="small">L’import CSV fonctionne sur le format de travail fourni. Les connexions bancaires, imports camt et formats des prestataires seront ajoutés après réception de leurs exemples.</p><div class="divider"></div><p class="small"><strong>Prélèvement automatique</strong></p><p class="micro muted">Aucun mandat ni débit n’est créé ici. Le dispositif, la couverture des banques des locataires et les autorisations devront être validés avec les prestataires concernés.</p></div></article></div>` +
    `<article class="card mt"><div class="card-head"><h2>Essayer les situations à anticiper</h2></div><div class="card-body"><div class="mini-row"><div><strong>Un paiement est saisi ailleurs</strong><p class="micro muted">Le solde du faux SiteLink change. Le prochain enregistrement vérifie le solde avant d’imputer un montant.</p></div>${btn('Ajouter un règlement fictif de CHF 10', 'external-change', '', 'tiny', 'wallet')}</div><div class="mini-row"><div><strong>La confirmation d’une opération se perd</strong><p class="micro muted">Le reçu est créé dans le système fictif ; une actualisation ou une nouvelle tentative retrouve son identifiant sans doubler l’encaissement.</p></div>${btn('Tester une réponse perdue', 'lost-ack', '', 'tiny', 'info', count === 0)}</div><div class="mini-row"><div><strong>Repartir du scénario de départ</strong><p class="micro muted">Restaure les seuls dossiers fictifs de cet atelier.</p></div>${btn('Réinitialiser', 'reset', '', 'tiny danger', 'refresh')}</div></div></article><div class="notice mt">${icon('file')}<span>La lecture et l’écriture des règlements externes dans SiteLink devront être confirmées par Storable. Ce connecteur fictif ne démontre pas la compatibilité de leur API réelle.</span></div>`;
}
function historyPage(s) {return head('SAVOIR CE QUI A ÉTÉ FAIT', 'Un historique lisible.', 'Imports, affectations, actualisations et brouillons restent traçables dans ce navigateur.') + `<article class="card"><div class="card-body"><ul class="timeline">${s.events.map(e => `<li>${esc(e.message)}<time>${date(e.at)} à ${time(e.at)}</time></li>`).join('')}</ul></div></article>`;}
function boxesPage(s, u) {
  const units = s.units.filter(x => (u.centre === 'all' || x.centre === u.centre) && (!u.query || (x.label + x.centre).toLowerCase().includes(u.query.toLowerCase())));
  return head('LES LOCATIONS, EN UN COUP D’ŒIL', 'Des box reliés aux dossiers.', 'Vue de démonstration en lecture seule. Dans le raccordement envisagé, les disponibilités viendraient de SiteLink.') + `<article class="card"><div class="card-body"><div class="box-grid">${units.map(x => `<div class="box-card ${x.status === 'Libre' ? 'free' : ''}">${icon('box')}<strong>${esc(x.label)}</strong><p>${x.area} m² · ${esc(x.status)}</p><p>${esc(x.centre)}</p>${x.clientId ? `<div class="mt">${btn(s.clients.find(c => c.id === x.clientId)?.name || 'Voir le client', 'client', x.clientId, 'tiny ghost')}</div>` : ''}</div>`).join('')}</div></div></article>`;
}

export function renderApp(s, u) {
  const nav = [['overview', 'À rapprocher', 'dashboard'], ['import', 'Importer', 'upload'], ['clients', 'Dossiers clients', 'users'], ['payments', 'Paiements', 'wallet'], ['reminders', 'Rappels', 'bell'], ['boxes', 'Mes box', 'box'], ['connection', 'Connexions', 'link'], ['history', 'Historique', 'clock']];
  const title = nav.find(x => x[0] === u.page)?.[1] || 'À rapprocher';
  const pages = {overview: () => overview(s, u), import: () => importPage(s, u), clients: () => clientsPage(s, u), payments: () => paymentsPage(s, u), reminders: () => reminderPage(s), connection: () => connectionPage(s), history: () => historyPage(s), boxes: () => boxesPage(s, u)};
  return `<div class="layout"><aside class="sidebar"><a class="brand" href="#/overview"><span class="mark">c</span>chantelio<b>ATELIER</b></a><div class="workspace">${icon('wallet')}<div><strong>Atelier paiements</strong><br><span class="muted">Centres fictifs · Suisse · CHF</span></div></div><div class="nav-label">COMPRENDRE ET PRÉPARER</div><nav aria-label="Navigation principale">${nav.map(([id, name, ico]) => `<a href="#/${id}" class="nav-item ${id === u.page ? 'active' : ''}"${id === u.page ? ' aria-current="page"' : ''}>${icon(ico)}${name}${id === 'overview' ? `<span class="nav-count">${s.payments.filter(p => ['matched', 'partial', 'review', 'overpayment'].includes(proposalFor(s, p).status)).length}</span>` : ''}</a>`).join('')}</nav><div class="sidebar-note"><strong>Une base pour le projet.</strong>Les règles d’import et de rapprochement fonctionnent sur des données fictives. Les connexions réelles restent à développer.</div><div class="profile"><span class="avatar">IL</span><div><strong>Inès Lebib</strong><br><span class="muted">Espace de préparation</span></div></div></aside><div class="main-wrap"><header class="topbar"><div class="row"><button class="mobile-button" data-action="menu" aria-label="Afficher le menu">${icon('menu')}</button><span class="context">Atelier / ${title}</span></div><div class="row"><label class="search-label" for="global-query">Rechercher dans les dossiers et paiements</label><input id="global-query" data-change="query" type="search" placeholder="Rechercher… puis Entrée" value="${esc(u.query)}"><label class="search-label" for="centre">Centre</label><select id="centre" data-change="centre"><option value="all">Tous les centres · CHF</option>${[...new Set(s.clients.map(c => c.centre))].map(x => `<option value="${esc(x)}"${u.centre === x ? ' selected' : ''}>${esc(x)}</option>`).join('')}</select><span class="avatar">IL</span></div></header><main id="main" class="main">${notice('<strong>Prototype avec données fictives.</strong> Connecteur SiteLink simulé · aucun débit réel · aucun message envoyé.')}${(pages[u.page] || pages.overview)()}<footer class="footer"><span>Scénario du 2 novembre 2026 · modifications conservées dans ce navigateur</span><span>Atelier privé · données non partagées entre visiteurs</span></footer></main></div></div>`;
}

export function renderDrawer(s, u) {
  if (!u.drawer) return '';
  const {kind, id} = u.drawer; let title = '', body = '', sub = '';
  if (kind === 'payment') {
    const p = s.payments.find(p => p.id === id); if (!p) return '';
    const match = proposalFor(s, p), operations = s.operations.filter(op => op.paymentId === p.id);
    title = p.customer || 'Paiement à identifier'; sub = p.transactionId;
    const invoices = s.invoices.filter(i => i.currency === p.currency && availableDue(s, i.id) > 0);
    const selected = match.invoiceId || (match.candidates.length === 1 ? match.candidates[0] : '');
    body = `${badge(match.status)}<div class="detail-grid"><div><span>Montant reçu</span><strong>${esc(money(p.amountCents, p.currency))}</strong></div><div><span>Moyen / date</span><strong>${esc(p.method)} · ${date(p.date)}</strong></div><div><span>Référence d’origine</span><strong>${esc(p.reference || 'Absente')}</strong></div><div><span>Montant encore à affecter</span><strong>${esc(money(availablePayment(s, id), p.currency))}</strong></div></div>${notice(esc(match.reason), ['review', 'overpayment', 'uncertain'].includes(match.status))}<p class="micro muted mt">${esc(p.description)}</p>`;
    if (p.kind === 'payment' && availablePayment(s, id) > 0 && invoices.length) {
      const amount = selected ? Math.min(availablePayment(s, id), availableDue(s, selected)) : availablePayment(s, id);
      body += `<section class="drawer-section"><h3>Confirmer l’affectation</h3><form data-form="allocate" data-id="${esc(id)}"><div class="field"><label for="invoice-select">Facture / location</label><select id="invoice-select" name="invoice" data-allocation-invoice required><option value="">Choisir après vérification</option>${invoices.map(i => `<option value="${esc(i.id)}"${i.id === selected ? ' selected' : ''}>${esc(clientFor(s, i).name)} · ${esc(i.reference)} · ${esc(money(availableDue(s, i.id), i.currency))}</option>`).join('')}</select></div><div class="form-grid"><div class="field"><label for="allocation-amount">Montant à affecter (${esc(p.currency)})</label><input id="allocation-amount" name="amount" inputmode="decimal" required value="${(amount / 100).toFixed(2)}"></div><div class="field"><label>Effet</label><p class="micro muted">Une préparation est créée. Aucun paiement n’est encore enregistré dans le système fictif.</p></div></div><button type="submit" class="btn primary">${icon('check')}Confirmer la préparation</button></form></section>`;
    }
    if (operations.length) body += `<section class="drawer-section"><h3>Les affectations de ce règlement</h3>${operations.map(op => {const i = s.invoices.find(i => i.id === op.invoiceId); return `<div class="mini-row"><div><strong>${esc(i?.reference)} · ${esc(money(op.amountCents, op.currency))}</strong><p class="micro muted">${esc({queued: 'Préparé', synced: 'Enregistré en simulation', uncertain: 'Confirmation incertaine', failed: 'À reprendre'}[op.status])}${op.receiptId ? ' · ' + esc(op.receiptId) : ''}</p>${op.error ? `<p class="micro" style="color:var(--red)">${esc(op.error)}</p>` : ''}</div>${op.status === 'queued' ? btn('Retirer', 'cancel-operation', op.id, 'tiny danger') : ''}</div>`;}).join('')}${operations.some(op => ['queued', 'uncertain'].includes(op.status)) ? `<div class="mt">${btn('Simuler l’enregistrement des préparations', 'sync', '', 'primary', 'link')}</div>` : ''}</section>`;
    body += `<section class="drawer-section"><h3>Historique de cette opération</h3><ul class="timeline"><li>Import de l’opération d’origine.<time>${date(p.importedAt)} à ${time(p.importedAt)}</time></li>${s.events.filter(e => e.target === p.id).map(e => `<li>${esc(e.message)}<time>${time(e.at)}</time></li>`).join('')}</ul></section>`;
  } else if (kind === 'client') {
    const client = s.clients.find(c => c.id === id); if (!client) return '';
    title = client.name; sub = client.centre;
    const invoices = s.invoices.filter(i => i.clientId === client.id);
    body = `<p class="small muted">${esc(client.email)}</p><div class="detail-grid"><div><span>Solde dans la source simulée</span><strong>${esc(money(invoices.reduce((sum, i) => sum + i.balanceCents, 0)))}</strong></div><div><span>Box</span><strong>${s.units.filter(x => x.clientId === id).map(x => esc(x.label)).join(', ')}</strong></div></div><h3>Factures et suivi des règlements</h3>${invoices.map(i => `<section class="drawer-section"><div class="row between"><strong>${esc(i.reference)}</strong>${chip(i.balanceCents === 0 ? 'Soldée en simulation' : 'Solde à suivre', i.balanceCents === 0 ? '' : 'amber')}</div><p class="micro muted">${esc(i.period)} · échéance ${date(i.due)}</p><div class="mini-row"><span>Solde provenant du faux connecteur</span><strong>${esc(money(i.balanceCents, i.currency))}</strong></div>${s.operations.filter(op => op.invoiceId === i.id && op.status !== 'failed').map(op => {const p = s.payments.find(p => p.id === op.paymentId); return `<div class="mini-row"><div><strong>${esc(p.method)} · ${esc(money(op.amountCents, op.currency))}</strong><p class="micro muted">${esc(op.status === 'synced' ? 'Reçu simulé : ' + op.receiptId : 'Préparation en cours')}</p></div>${btn('Voir', 'payment', p.id, 'tiny', 'arrow')}</div>`;}).join('')}</section>`).join('')}`;
  } else if (kind === 'draft') {
    const d = s.reminders.find(d => d.id === id); if (!d) return '';
    title = 'Relire le brouillon'; sub = 'Aucun message n’est envoyé'; body = `<pre>${esc(d.text)}</pre><div class="mt">${btn('Copier le brouillon', 'copy-draft', id, 'primary', 'file')}</div><p class="micro muted mt">Le solde et les vérifications seront contrôlés à nouveau avant la copie.</p>`;
  } else if (kind === 'reset') {
    title = 'Repartir du scénario de départ'; sub = 'Atelier avec données fictives'; body = `<p class="small">Cette action restaure les encaissements et les dossiers d’exemple de cet atelier. Les préparations, brouillons et imports locaux seront retirés.</p><div class="mt">${btn('Restaurer le scénario', 'reset-confirm', '', 'danger', 'refresh')}</div>`;
  }
  return `<div class="modal-backdrop" data-backdrop><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><header class="drawer-head"><div><div class="eyebrow">${esc(sub)}</div><h2 id="drawer-title">${esc(title)}</h2></div><button class="btn tiny ghost" data-action="close" aria-label="Fermer la fiche">${icon('close')}</button></header><div class="drawer-body">${body}</div></section></div>`;
}
